  1	// @vitest-environment jsdom
  2	
  3	/**
  4	 * Tests for gui/public/views/orchestrator.js — WP-011
  5	 *
  6	 * All acceptance criteria tested:
  7	 *   AC-1: "Run Preflight" calls API.orchestratorStart(planPath, true) and
  8	 *         renders a pass/fail checklist.
  9	 *   AC-2: "Start Run" button disabled initially; enabled only when all
 10	 *         preflight checks pass; calls API.orchestratorStart(planPath, false).
 11	 *   AC-3: Queue table fetches on render and registers 5-second polling via
 12	 *         Router._setPolling. Each entry renders status badge, elapsed time,
 13	 *         and progress.
 14	 *   AC-4: Pending entries show kill button; started entries show project link;
 15	 *         dead entries show dismiss button.
 16	 *   AC-5: Expanding a row starts a log preview via
 17	 *         OrchestratorWidgets.renderLogPreview(); re-render calls its cleanup.
 18	 *   AC-6: CLI reference card HTML is present at the bottom of the view.
 19	 *   AC-7: All log preview cleanup functions are invoked when renderOrchestrator
 20	 *         is called a second time (re-render scenario).
 21	 *
 22	 * Uses jsdom + vm.runInThisContext to load the browser-side script.
 23	 * API, Router, OrchestratorWidgets, and escapeHtml are set on globalThis.
 24	 */
 25	
 26	import { describe, it, expect, beforeAll, beforeEach, afterEach, vi, type Mock } from 'vitest';
 27	import { readFileSync } from 'node:fs';
 28	import { join } from 'node:path';
 29	import vm from 'node:vm';
 30	import type { QueueEntry } from '../../src/gui/queue/types.js';
 31	
 32	// ---------------------------------------------------------------------------
 33	// Load scripts
 34	// ---------------------------------------------------------------------------
 35	
 36	const publicDir = join(__dirname, '../../gui/public');
 37	
 38	const utilsJs        = readFileSync(join(publicDir, 'utils.js'), 'utf-8');
 39	const orchestratorJs = readFileSync(join(publicDir, 'views/orchestrator.js'), 'utf-8');
 40	
 41	// ---------------------------------------------------------------------------
 42	// Global type stubs
 43	// ---------------------------------------------------------------------------
 44	
 45	declare global {
 46	  // eslint-disable-next-line no-var
 47	  var renderOrchestrator: (app: HTMLElement) => void;
 48	  // eslint-disable-next-line no-var
 49	  var API: {
 50	    orchestratorStart:    Mock;
 51	    orchestratorGetQueue: Mock;
 52	    orchestratorKill:     Mock;
 53	    orchestratorDismiss:  Mock;
 54	  };
 55	  // eslint-disable-next-line no-var
 56	  var Router: {
 57	    _setPolling: Mock;
 58	    _clearPolling: Mock;
 59	  };
 60	  // eslint-disable-next-line no-var
 61	  var OrchestratorWidgets: {
 62	    renderCliReference:  Mock;
 63	    renderKillButton:    Mock;
 64	    renderDismissButton: Mock;
 65	    renderLogPreview:    Mock;
 66	    renderProgressBadge: Mock;
 67	    renderStatusCard:    Mock;
 68	  };
 69	}
 70	
 71	// ---------------------------------------------------------------------------
 72	// Setup: install globals, load scripts once
 73	// ---------------------------------------------------------------------------
 74	
 75	beforeAll(() => {
 76	  // Install utils.js globals (escapeHtml, etc.)
 77	  vm.runInThisContext(utilsJs);
 78	
 79	  // Stub API — individual tests override as needed via mockResolvedValue.
 80	  (globalThis as Record<string, unknown>)['API'] = {
 81	    orchestratorStart:    vi.fn().mockResolvedValue({ checks: [], started: false }),
 82	    orchestratorGetQueue: vi.fn().mockResolvedValue([]),
 83	    orchestratorKill:     vi.fn().mockResolvedValue(null),
 84	    orchestratorDismiss:  vi.fn().mockResolvedValue(null),
 85	  };
 86	
 87	  // Stub Router.
 88	  (globalThis as Record<string, unknown>)['Router'] = {
 89	    _setPolling:   vi.fn(),
 90	    _clearPolling: vi.fn(),
 91	  };
 92	
 93	  // Stub OrchestratorWidgets.
 94	  (globalThis as Record<string, unknown>)['OrchestratorWidgets'] = {
 95	    renderCliReference:  vi.fn().mockReturnValue('<div class="cli-reference">CLI Ref</div>'),
 96	    renderKillButton:    vi.fn().mockImplementation((_id: string, _cb: () => void) => {
 97	      const btn = document.createElement('button');
 98	      btn.className = 'kill-btn';
 99	      btn.textContent = 'Kill';
100	      return btn;

101	    }),
102	    renderDismissButton: vi.fn().mockImplementation((_id: string, _cb: () => void) => {
103	      const btn = document.createElement('button');
104	      btn.className = 'dismiss-btn';
105	      btn.textContent = 'Dismiss';
106	      return btn;
107	    }),
108	    renderLogPreview:    vi.fn().mockReturnValue(vi.fn()), // returns cleanup stub
109	    renderProgressBadge: vi.fn().mockReturnValue('<span class="badge-neutral">• idle</span>'),
110	    renderStatusCard:    vi.fn().mockReturnValue('<div>card</div>'),
111	  };
112	
113	  // Load the orchestrator view script.
114	  vm.runInThisContext(orchestratorJs);
115	});
116	
117	// Reset mocks before each test; restore real timers.
118	beforeEach(() => {
119	  vi.clearAllMocks();
120	
121	  // Reset to safe defaults.
122	  globalThis.API.orchestratorStart    = vi.fn().mockResolvedValue({ checks: [], started: false });
123	  globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([]);
124	  globalThis.OrchestratorWidgets.renderCliReference = vi.fn()
125	    .mockReturnValue('<div class="cli-reference">CLI Ref</div>');
126	  globalThis.OrchestratorWidgets.renderProgressBadge = vi.fn()
127	    .mockReturnValue('<span class="badge-neutral">• idle</span>');
128	  globalThis.OrchestratorWidgets.renderKillButton = vi.fn()
129	    .mockImplementation((_id: string, _cb: () => void) => {
130	      const btn = document.createElement('button');
131	      btn.className = 'kill-btn';
132	      btn.textContent = 'Kill';
133	      return btn;
134	    });
135	  globalThis.OrchestratorWidgets.renderDismissButton = vi.fn()
136	    .mockImplementation((_id: string, _cb: () => void) => {
137	      const btn = document.createElement('button');
138	      btn.className = 'dismiss-btn';
139	      btn.textContent = 'Dismiss';
140	      return btn;
141	    });
142	  globalThis.OrchestratorWidgets.renderLogPreview = vi.fn()
143	    .mockReturnValue(vi.fn());
144	});
145	
146	afterEach(() => {
147	  vi.restoreAllMocks();
148	});
149	
150	// ---------------------------------------------------------------------------
151	// Helpers
152	// ---------------------------------------------------------------------------
153	
154	/**
155	 * Flush pending microtask queues so that chained Promise callbacks resolve
156	 * before assertions run.
157	 *
158	 * The loop runs 10 times because the async paths under test involve multiple
159	 * hops — e.g. orchestratorGetQueue resolves → renderQueueTable is called →
160	 * DOM mutations fire — each of which queues a fresh microtask tick.  One or
161	 * two iterations are not sufficient to drain these chains; 10 was chosen
162	 * empirically to cover all current paths with a comfortable margin.  If a
163	 * future test introduces a longer chain, increase this count accordingly.
164	 */
165	async function flushPromises(): Promise<void> {
166	  for (let i = 0; i < 10; i++) await Promise.resolve();
167	}
168	
169	/** Create a fresh #app element. */
170	function makeApp(): HTMLElement {
171	  const app = document.createElement('div');
172	  app.id = 'app';
173	  document.body.appendChild(app);
174	  return app;
175	}
176	
177	function cleanupApp(app: HTMLElement): void {
178	  app.remove();
179	}
180	
181	/** Build a minimal queue entry object. */
182	function makeEntry(overrides: Partial<QueueEntry> = {}): QueueEntry {
183	  return {
184	    id:              'entry-abc',
185	    pid:             12345,
186	    planPath:        '/home/user/project/plan.md',
187	    expectedSlug:    'my-project',
188	    startedAt:       new Date(Date.now() - 70_000).toISOString(),
189	    status:          'pending' as const,
190	    effectiveStatus: 'pending',
191	    projectExists:   true,
192	    progress:        null,
193	    lastAction:      null,
194	    logFilename:     null,
195	    ...overrides,
196	  };
197	}
198	
199	// ---------------------------------------------------------------------------
200	// AC-6: CLI reference card
201	// ---------------------------------------------------------------------------
202	
203	describe('renderOrchestrator — AC-6: CLI reference', () => {
204	  it('renders the CLI reference card returned by OrchestratorWidgets', async () => {
205	    const app = makeApp();
206	    try {
207	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([]);
208	      globalThis.OrchestratorWidgets.renderCliReference = vi.fn()
209	        .mockReturnValue('<div class="cli-reference">CLI COMMANDS</div>');
210	      renderOrchestrator(app);
211	      await flushPromises();
212	      expect(app.innerHTML).toContain('CLI COMMANDS');
213	    } finally { cleanupApp(app); }
214	  });
215	
216	  it('calls OrchestratorWidgets.renderCliReference()', () => {
217	    const app = makeApp();
218	    try {
219	      renderOrchestrator(app);
220	      expect(globalThis.OrchestratorWidgets.renderCliReference).toHaveBeenCalled();
221	    } finally { cleanupApp(app); }
222	  });
223	});
224	
225	// ---------------------------------------------------------------------------
226	// AC-3: Queue table + polling
227	// ---------------------------------------------------------------------------
228	
229	describe('renderOrchestrator — AC-3: queue + polling', () => {
230	  it('calls API.orchestratorGetQueue on render', async () => {
231	    const app = makeApp();
232	    try {
233	      renderOrchestrator(app);
234	      await flushPromises();
235	      expect(globalThis.API.orchestratorGetQueue).toHaveBeenCalledOnce();
236	    } finally { cleanupApp(app); }
237	  });
238	
239	  it('registers polling via Router._setPolling with 5000 ms', () => {
240	    const app = makeApp();
241	    try {
242	      renderOrchestrator(app);
243	      expect(globalThis.Router._setPolling).toHaveBeenCalledOnce();
244	      const [, delay] = (globalThis.Router._setPolling as Mock).mock.calls[0];
245	      expect(delay).toBe(5000);
246	    } finally { cleanupApp(app); }
247	  });
248	
249	  it('renders empty state message when queue is empty', async () => {
250	    const app = makeApp();
251	    try {
252	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([]);
253	      renderOrchestrator(app);
254	      await flushPromises();
255	      expect(app.innerHTML).toContain('No active runs');
256	    } finally { cleanupApp(app); }
257	  });
258	
259	  it('renders a table row for each queue entry', async () => {
260	    const app = makeApp();
261	    try {
262	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
263	        makeEntry({ id: 'e1' }),
264	        makeEntry({ id: 'e2' }),
265	      ]);
266	      renderOrchestrator(app);
267	      await flushPromises();
268	      const rows = app.querySelectorAll('.orch-queue-row');
269	      expect(rows.length).toBe(2);
270	    } finally { cleanupApp(app); }
271	  });
272	
273	  it('shows plan basename (not full path) in plan cell', async () => {
274	    const app = makeApp();
275	    try {
276	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
277	        makeEntry({ planPath: '/long/path/to/plan.md' }),
278	      ]);
279	      renderOrchestrator(app);
280	      await flushPromises();
281	      const planCell = app.querySelector('.orch-plan-cell');
282	      expect(planCell?.textContent?.trim()).toBe('plan.md');
283	    } finally { cleanupApp(app); }
284	  });
285	
286	  it('shows full path as a tooltip on the plan cell', async () => {
287	    const app = makeApp();
288	    try {
289	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
290	        makeEntry({ planPath: '/long/path/to/plan.md' }),
291	      ]);
292	      renderOrchestrator(app);
293	      await flushPromises();
294	      const planCell = app.querySelector('.orch-plan-cell');
295	      expect(planCell?.getAttribute('title')).toBe('/long/path/to/plan.md');
296	    } finally { cleanupApp(app); }
297	  });
298	
299	  it('renders a status badge for each entry', async () => {
300	    const app = makeApp();

301	    try {
302	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
303	        makeEntry({ effectiveStatus: 'pending' }),
304	      ]);
305	      renderOrchestrator(app);
306	      await flushPromises();
307	      const badge = app.querySelector('.badge-pending');
308	      expect(badge).not.toBeNull();
309	    } finally { cleanupApp(app); }
310	  });
311	
312	  it('calls OrchestratorWidgets.renderProgressBadge for each entry', async () => {
313	    const app = makeApp();
314	    try {
315	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
316	        makeEntry(),
317	        makeEntry({ id: 'entry-xyz' }),
318	      ]);
319	      renderOrchestrator(app);
320	      await flushPromises();
321	      expect(globalThis.OrchestratorWidgets.renderProgressBadge).toHaveBeenCalledTimes(2);
322	    } finally { cleanupApp(app); }
323	  });
324	});
325	
326	// ---------------------------------------------------------------------------
327	// AC-4: Per-status row actions
328	// ---------------------------------------------------------------------------
329	
330	describe('renderOrchestrator — AC-4: row actions', () => {
331	  it('shows kill button for pending entries', async () => {
332	    const app = makeApp();
333	    try {
334	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
335	        makeEntry({ effectiveStatus: 'pending' }),
336	      ]);
337	      renderOrchestrator(app);
338	      await flushPromises();
339	      expect(app.querySelector('.kill-btn')).not.toBeNull();
340	      expect(globalThis.OrchestratorWidgets.renderKillButton).toHaveBeenCalledOnce();
341	    } finally { cleanupApp(app); }
342	  });
343	
344	  it('shows project link for started entries', async () => {
345	    const app = makeApp();
346	    try {
347	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
348	        makeEntry({ effectiveStatus: 'started', expectedSlug: 'my-project' }),
349	      ]);
350	      renderOrchestrator(app);
351	      await flushPromises();
352	      const link = app.querySelector('.orch-project-link') as HTMLAnchorElement | null;
353	      expect(link).not.toBeNull();
